def logistic_map(width, height, supply_x, supply_y):
    if not supply_x or not supply_y:
        return [[None] * width for _ in range(height)]

    result = [[float('inf')] * width for _ in range(height)]

    for sx in supply_x:
        for sy in supply_y:
            for i in range(height):
                for j in range(width):
                    result[i][j] = min(result[i][j], abs(i - sy) + abs(j - sx))

    return result
